import assert from 'node:assert/strict';
import {spawn} from 'node:child_process';
import {mkdtemp,readFile,rm,mkdir,writeFile} from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
const profile=await mkdtemp(path.join(os.tmpdir(),'legendgirl-fairy-chrome-'));
const chrome=spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',['--headless=new','--mute-audio','--no-first-run','--no-default-browser-check','--autoplay-policy=no-user-gesture-required','--remote-debugging-port=0','--user-data-dir='+profile,'about:blank'],{stdio:'ignore'});
let ws;
try{
 let port;for(let i=0;i<120;i++){try{port=(await readFile(path.join(profile,'DevToolsActivePort'),'utf8')).split('\n')[0];break;}catch{}await new Promise(r=>setTimeout(r,100));}assert.ok(port,'Chrome iniciou');
 const tabs=await(await fetch('http://127.0.0.1:'+port+'/json/list')).json();ws=new WebSocket(tabs.find(t=>t.type==='page').webSocketDebuggerUrl);await new Promise(r=>ws.onopen=r);
 let id=0;const pending=new Map(),errors=[];ws.onmessage=e=>{const d=JSON.parse(e.data);if(d.id){pending.get(d.id)?.(d);pending.delete(d.id);}if(d.method==='Runtime.exceptionThrown')errors.push(d.params.exceptionDetails);};
 const call=(method,params={})=>new Promise(resolve=>{pending.set(++id,resolve);ws.send(JSON.stringify({id,method,params}));});
 await call('Runtime.enable');await call('Page.navigate',{url:'http://127.0.0.1:3000/?debug=1'});await new Promise(r=>setTimeout(r,1500));
 const response=await call('Runtime.evaluate',{awaitPromise:true,returnByValue:true,expression:`import('/docs/diario-ia/qa/fada-3d-20261022/analise.js').then(m=>m.run())`});
 if(response.result?.exceptionDetails)throw Error(JSON.stringify(response.result.exceptionDetails));
 const data=response.result?.result?.value;assert.ok(data,'Resultado recebido');
 const out='docs/diario-ia/qa-resultados/fada-3d';await mkdir(out,{recursive:true});await mkdir('/tmp/legendgirl-fairy-preview',{recursive:true});
 for(const shot of data.capturas){const bytes=Buffer.from(shot.data.split(',')[1],'base64');await writeFile(path.join(out,shot.nome+'.png'),bytes);await writeFile('/tmp/legendgirl-fairy-preview/'+shot.nome+'.png',bytes);delete shot.data;}
 await writeFile(path.join(out,'resultado.json'),JSON.stringify(data,null,2));console.log(JSON.stringify(data,null,2));
 assert.deepEqual(errors,[],'Sem exceções do navegador');assert.ok(data.resultados.every(r=>r.estadoPreservado),'Apresentação não altera simulação');
 assert.ok(data.resultados.every(r=>r.sombrasAtivas===2&&r.mapas<=2),'No máximo dois mapas de sombra');
 assert.ok(data.resultados.every(r=>r.calls<310),'Orçamento de chamadas por quadro');
 assert.ok(data.resultados.every(r=>r.iluminadosMenina>20&&r.sombraMenina>8&&r.sombraCena>20),'Luz e sombras alteram pixels reais da menina e cena');
 assert.ok(data.resultados.every(r=>r.aoRedor&&r.projecaoVisivel),'Fada ao redor da menina, dentro do quadro');
 assert.ok(data.modelo.profundidade>.2&&data.modelo.triangulos<3500&&data.modelo.malhas<=6,'Modelo volumétrico compacto');
 assert.ok(data.percursos.every(p=>p.stage==='COMPLETE'&&p.hits===0&&p.maxCalls<310&&p.maxShadows===2),'Percurso completo e orçamento nas duas dificuldades');
 assert.ok(data.orbita.doisLados&&data.orbita.frenteAtras&&data.orbita.alturaVariavel&&data.orbita.luzAcompanha,'Órbita real e luz presa ao núcleo');
 assert.ok(data.pausa&&data.descarte,'Pausa determinística e descarte dos recursos');
}finally{ws?.close();chrome.kill();await new Promise(r=>chrome.once('exit',r));await rm(profile,{recursive:true,force:true});}
